// Package main provides a pre-test bootstrap command that runs agent-specific
// setup (auth config, warmup) before E2E tests. Usage: go run ./e2e/bootstrap
package main

import (
	"fmt"
	"os"

	"github.com/entireio/cli/e2e/agents"
)

func main() {
	// Optional: pass agent name as argument to bootstrap only that agent.
	filter := ""
	if len(os.Args) > 1 {
		filter = os.Args[1]
	}

	for _, a := range agents.All() {
		if filter != "" && a.Name() != filter {
			continue
		}
		fmt.Fprintf(os.Stderr, "bootstrapping %s...\n", a.Name())
		if err := a.Bootstrap(); err != nil {
			fmt.Fprintf(os.Stderr, "bootstrap %s: %v\n", a.Name(), err)
			os.Exit(1)
		}
		fmt.Fprintf(os.Stderr, "bootstrapping %s: done\n", a.Name())
	}
}


--- e2e/agents/agent.go
package agents

import (
	"context"
	"os"
	"strconv"
	"strings"
	"time"
)

type Output struct {
	Command  string
	Stdout   string
	Stderr   string
	ExitCode int
}

type Option func(*runConfig)
type runConfig struct {
	Model          string
	PermissionMode string
	PromptTimeout  time.Duration
}

func WithModel(model string) Option {
	return func(c *runConfig) { c.Model = model }
}

func WithPermissionMode(mode string) Option {
	return func(c *runConfig) { c.PermissionMode = mode }
}

func WithPromptTimeout(d time.Duration) Option {
	return func(c *runConfig) { c.PromptTimeout = d }
}

type Agent interface {
	Name() string
	// Binary returns the CLI binary name (e.g. "claude", "gemini").
	Binary() string
	EntireAgent() string
	PromptPattern() string
	// TimeoutMultiplier returns a factor applied to per-test timeouts.
	// Slower agents (e.g. Gemini) return values > 1.
	TimeoutMultiplier() float64
	RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error)
	StartSession(ctx context.Context, dir string) (Session, error)
	// Bootstrap performs one-time CI setup (auth config, warmup, etc.).
	// Called before any tests run. Implementations should be idempotent.
	Bootstrap() error
	// IsTransientError returns true if the error from RunPrompt looks like
	// a transient API failure (e.g. 500, rate limit, network error) that
	// is worth retrying.
	IsTransientError(out Output, err error) bool
}

type Session interface {
	Send(input string) error
	WaitFor(pattern string, timeout time.Duration) (string, error)
	Capture() string
	Close() error
}

// ExternalAgent is an optional interface for agents discovered via the
// external agent protocol (entire-agent-* binaries). SetupRepo uses this
// to pre-configure external_agents in settings before running `entire enable`.
type ExternalAgent interface {
	IsExternalAgent() bool
}

var registry []Agent
var gates = map[string]chan struct{}{}

func Register(a Agent) {
	registry = append(registry, a)
}

// RegisterGate sets a concurrency limit for an agent's tests.
// Tests call AcquireSlot/ReleaseSlot to respect this limit.
// The limit can be overridden via E2E_CONCURRENT_TEST_LIMIT.
func RegisterGate(name string, defaultMax int) {
	max := defaultMax
	if v, err := strconv.Atoi(os.Getenv("E2E_CONCURRENT_TEST_LIMIT")); err == nil && v > 0 {
		max = v
	}
	gates[name] = make(chan struct{}, max)
}

// AcquireSlot blocks until a test slot is available for the agent or the
// context is cancelled. Returns a non-nil error if the context expires
// before a slot opens.
func AcquireSlot(ctx context.Context, a Agent) error {
	g, ok := gates[a.Name()]
	if !ok {
		return nil
	}
	select {
	case g <- struct{}{}:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

// ReleaseSlot frees a test slot for the agent.
func ReleaseSlot(a Agent) {
	if g, ok := gates[a.Name()]; ok {
		<-g
	}
}

func All() []Agent {
	return registry
}

// filterEnv returns env with entries matching any of the given variable names
// removed. Used to strip test-only overrides (e.g. ENTIRE_TEST_TTY) from agent
// processes so they exercise real detection paths.
func filterEnv(env []string, names ...string) []string {
	out := make([]string, 0, len(env))
	for _, e := range env {
		skip := false
		for _, name := range names {
			if strings.HasPrefix(e, name+"=") {
				skip = true
				break
			}
		}
		if !skip {
			out = append(out, e)
		}
	}
	return out
}


--- e2e/agents/claude.go
package agents

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"time"
)

// cleanEnv returns os.Environ() with agent-incompatible variables removed.
// It strips CLAUDECODE (so Claude Code doesn't refuse to start inside this
// test runner) and ENTIRE_TEST_TTY (so agents exercise the real TTY detection
// paths instead of the test override).
func cleanEnv() []string {
	var env []string
	for _, e := range os.Environ() {
		if strings.HasPrefix(e, "CLAUDECODE=") || strings.HasPrefix(e, "ENTIRE_TEST_TTY=") {
			continue
		}
		env = append(env, e)
	}
	return env
}

func init() {
	if env := os.Getenv("E2E_AGENT"); env != "" && env != "claude-code" {
		return
	}
	Register(&Claude{})
}

type Claude struct{}

func (c *Claude) Name() string               { return "claude-code" }
func (c *Claude) Binary() string             { return "claude" }
func (c *Claude) EntireAgent() string        { return "claude-code" }
func (c *Claude) PromptPattern() string      { return `❯` }
func (c *Claude) TimeoutMultiplier() float64 { return 1.0 }

func (c *Claude) IsTransientError(out Output, _ error) bool {
	transientPatterns := []string{
		"overloaded",
		"rate limit",
		"529",
		"503",
		"ECONNRESET",
		"ETIMEDOUT",
	}
	for _, p := range transientPatterns {
		if strings.Contains(out.Stderr, p) {
			return true
		}
	}
	return false
}

func (c *Claude) Bootstrap() error {
	// On CI, write a config file so Claude Code uses the API key from the
	// environment instead of trying OAuth/Keychain.
	if os.Getenv("CI") == "" {
		return nil
	}
	apiKey := os.Getenv("ANTHROPIC_API_KEY")
	if apiKey == "" {
		return nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return fmt.Errorf("get home dir: %w", err)
	}
	dir := filepath.Join(home, ".claude")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return fmt.Errorf("mkdir %s: %w", dir, err)
	}
	config := fmt.Sprintf(`{"primaryApiKey":%q,"hasCompletedOnboarding":true}`, apiKey)
	path := filepath.Join(dir, ".claude.json")
	return os.WriteFile(path, []byte(config), 0o644)
}

func (c *Claude) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
	cfg := &runConfig{Model: "haiku"}
	for _, o := range opts {
		o(cfg)
	}

	configDir, err := cleanConfigDir()
	if err != nil {
		return Output{}, fmt.Errorf("create clean config dir: %w", err)
	}
	defer func() { _ = os.RemoveAll(configDir) }()

	env := append(cleanEnv(),
		"ACCESSIBLE=1",

		// See https://code.claude.com/docs/en/settings - without this setting Claude was going off and
		// trying to Git-clone its plugin marketplace, which meant calling git commands that could fail
		// due to a user's exotic config (e.g. in paul's case, needing SSH-keychain access granted every
		// time).  That's no good, so for the E2E tests, we tell Claude not to make calls to auto-update
		// itself, clone its plugins, etc.
		"CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC=1",
		"CLAUDE_CONFIG_DIR="+configDir,
	)

	args := []string{"-p", prompt, "--model", cfg.Model, "--dangerously-skip-permissions"}
	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "--dangerously-skip-permissions"}
	cmd := exec.CommandContext(ctx, c.Binary(), args...)
	cmd.Dir = dir
	cmd.Stdin = nil
	cmd.Env = env
	setupProcessGroup(cmd)
	cmd.WaitDelay = 5 * time.Second

	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err = cmd.Run()
	exitCode := 0
	if err != nil {
		exitErr := &exec.ExitError{}
		if errors.As(err, &exitErr) {
			exitCode = exitErr.ExitCode()
		} else {
			exitCode = -1
		}
	}

	return Output{
		Command:  c.Binary() + " " + strings.Join(displayArgs, " "),
		Stdout:   stdout.String(),
		Stderr:   stderr.String(),
		ExitCode: exitCode,
	}, err
}

func (c *Claude) StartSession(ctx context.Context, dir string) (Session, error) {
	if runtime.GOOS == "windows" {
		return nil, nil //nolint:nilnil // nil session signals "not supported" per Agent interface contract
	}
	name := fmt.Sprintf("claude-test-%d", time.Now().UnixNano())

	configDir, err := cleanConfigDir()
	if err != nil {
		return nil, fmt.Errorf("create clean config dir: %w", err)
	}

	envArgs := []string{
		"ACCESSIBLE=1",

		// See https://code.claude.com/docs/en/settings - without this setting Claude was going off and
		// trying to Git-clone its plugin marketplace, which meant calling git commands that could fail
		// due to a user's exotic config (e.g. in paul's case, needing SSH-keychain access granted every
		// time).  That's no good, so for the E2E tests, we tell Claude not to make calls to auto-update
		// itself, clone its plugins, etc.
		"CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC=1",
		"CLAUDE_CONFIG_DIR=" + configDir,
	}

	args := append([]string{"env"}, envArgs...)
	args = append(args, c.Binary(), "--dangerously-skip-permissions")
	s, err := NewTmuxSession(name, dir, []string{"CLAUDECODE", "ENTIRE_TEST_TTY"}, args[0], args[1:]...)
	if err != nil {
		_ = os.RemoveAll(configDir)
		return nil, err
	}
	s.OnClose(func() { _ = os.RemoveAll(configDir) })

	// Dismiss startup dialogs until we reach the input prompt.
	for range 5 {
		content, err := s.WaitFor(`❯`, 15*time.Second)
		if err != nil {
			_ = s.Close()
			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
		}
		if !strings.Contains(content, "Enter to confirm") {
			break
		}
		// The bypass permissions dialog defaults to "No, exit" —
		// arrow down to "Yes, I accept" before confirming.
		if strings.Contains(content, "Yes, I accept") {
			_ = s.SendKeys("Down")
			time.Sleep(200 * time.Millisecond)
		}
		_ = s.SendKeys("Enter")
		time.Sleep(500 * time.Millisecond)
	}
	s.stableAtSend = ""

	return s, nil
}

// cleanConfigDir creates an isolated temp directory for CLAUDE_CONFIG_DIR so
// that E2E test runs don't inherit any user settings (CLAUDE.md, skills,
// projects, plugins, etc.).
func cleanConfigDir() (string, error) {
	dst, err := os.MkdirTemp("", "claude-config-*")
	if err != nil {
		return "", err
	}

	if os.Getenv("CI") != "" {
		if home, err := os.UserHomeDir(); err == nil {
			src := filepath.Join(home, ".claude", ".claude.json")
			if _, err := os.Stat(src); err == nil {
				_ = linkFile(src, filepath.Join(dst, ".claude.json"))
			}
		}
	} else {
		_ = os.WriteFile(filepath.Join(dst, ".claude.json"),
			[]byte(`{"hasCompletedOnboarding":true}`), 0o644)
	}

	return dst, nil
}


--- e2e/agents/codex.go
package agents

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

func init() {
	if env := os.Getenv("E2E_AGENT"); env != "" && env != "codex" {
		return
	}
	Register(&Codex{})
	RegisterGate("codex", 2)
}

// Codex implements the E2E Agent interface for OpenAI's Codex CLI.
type Codex struct{}

type CodexSession struct {
	*TmuxSession

	home string
}

func (s *CodexSession) Home() string { return s.home }

func (c *Codex) Name() string               { return "codex" }
func (c *Codex) Binary() string             { return "codex" }
func (c *Codex) EntireAgent() string        { return "codex" }
func (c *Codex) PromptPattern() string      { return `›` }
func (c *Codex) TimeoutMultiplier() float64 { return 1.5 }

func (c *Codex) Bootstrap() error {
	if os.Getenv("CI") != "" && os.Getenv("OPENAI_API_KEY") == "" {
		return errors.New("OPENAI_API_KEY must be set on CI for Codex E2E tests")
	}
	return nil
}

func (c *Codex) IsTransientError(out Output, err error) bool {
	if err == nil {
		return false
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return true
	}
	combined := out.Stdout + out.Stderr
	for _, p := range []string{"overloaded", "rate limit", "rate_limit", "503", "529", "ECONNRESET", "ETIMEDOUT"} {
		if strings.Contains(combined, p) {
			return true
		}
	}
	return false
}

// codexHome creates an isolated CODEX_HOME for a test run.
// Auth still works via OPENAI_API_KEY env var or symlinked auth.json.
//
// The directory lives under the user's home (not the system temp dir) because
// recent Codex versions refuse to install PATH helper binaries when CODEX_HOME
// sits under /tmp, which breaks subsequent tool calls.
func codexHome() (string, func(), error) {
	cache, err := os.UserCacheDir()
	if err != nil {
		return "", nil, fmt.Errorf("resolve user cache dir: %w", err)
	}
	base := filepath.Join(cache, "entire-e2e")
	if err := os.MkdirAll(base, 0o755); err != nil {
		return "", nil, fmt.Errorf("create codex home base %q: %w", base, err)
	}
	dir, err := os.MkdirTemp(base, "codex-home-*")
	if err != nil {
		return "", nil, fmt.Errorf("create temporary codex home under %q: %w", base, err)
	}
	return dir, func() { _ = os.RemoveAll(dir) }, nil
}

func (c *Codex) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
	cfg := &runConfig{}
	for _, o := range opts {
		o(cfg)
	}

	timeout := 60 * time.Second
	if cfg.PromptTimeout > 0 {
		timeout = cfg.PromptTimeout
	}
	promptCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	home, cleanup, err := codexHome()
	if err != nil {
		return Output{}, fmt.Errorf("create codex home: %w", err)
	}
	defer cleanup()

	absDir, err := filepath.Abs(dir)
	if err != nil {
		absDir = dir
	}
	if err := seedCodexHome(home, absDir); err != nil {
		return Output{}, fmt.Errorf("seed codex home: %w", err)
	}

	args := []string{"exec", "--dangerously-bypass-approvals-and-sandbox"}
	if cfg.Model != "" {
		args = append(args, "-m", cfg.Model)
	}
	args = append(args, prompt)

	env := append(filterEnv(os.Environ(), "ENTIRE_TEST_TTY", "CODEX_HOME"),
		"CODEX_HOME="+home,
	)

	cmd := exec.CommandContext(promptCtx, c.Binary(), args...)
	cmd.Dir = dir
	cmd.Stdin = nil
	cmd.Env = env
	setupProcessGroup(cmd)
	cmd.WaitDelay = 5 * time.Second

	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err = cmd.Run()
	exitCode := 0
	if err != nil {
		exitErr := &exec.ExitError{}
		if errors.As(err, &exitErr) {
			exitCode = exitErr.ExitCode()
		} else {
			exitCode = -1
		}
		if promptCtx.Err() == context.DeadlineExceeded {
			err = fmt.Errorf("%w: %w", err, context.DeadlineExceeded)
		}
	}

	return Output{
		Command:  c.Binary() + " " + strings.Join(args[:len(args)-1], " ") + " " + fmt.Sprintf("%q", prompt),
		Stdout:   stdout.String(),
		Stderr:   stderr.String(),
		ExitCode: exitCode,
	}, err
}

func (c *Codex) StartSession(ctx context.Context, dir string) (Session, error) {
	name := fmt.Sprintf("codex-test-%d", time.Now().UnixNano())

	home, cleanup, err := codexHome()
	if err != nil {
		return nil, fmt.Errorf("create codex home: %w", err)
	}

	absDir, err := filepath.Abs(dir)
	if err != nil {
		absDir = dir
	}
	if err := seedCodexHome(home, absDir); err != nil {
		cleanup()
		return nil, fmt.Errorf("seed codex home: %w", err)
	}

	s, err := c.startTmuxSession(name, dir, home, "codex", "--dangerously-bypass-approvals-and-sandbox")
	if err != nil {
		cleanup()
		return nil, err
	}
	s.OnClose(cleanup)

	// Dismiss startup dialogs (model upgrade prompts, etc.) until we reach
	// the input prompt. Similar to Claude's startup dialog handling.
	for range 5 {
		content, waitErr := s.WaitFor(c.PromptPattern(), 15*time.Second)
		if waitErr != nil {
			_ = s.Close()
			return nil, fmt.Errorf("waiting for codex prompt: %w", waitErr)
		}
		if !strings.Contains(content, "press enter to confirm") &&
			!strings.Contains(content, "Use ↑/↓ to move") {
			break
		}
		_ = s.SendKeys("Enter")
		time.Sleep(500 * time.Millisecond)
	}

	return &CodexSession{TmuxSession: s, home: home}, nil
}

func (c *Codex) ResumeSession(ctx context.Context, dir, home, sessionID string) (Session, error) {
	_ = ctx
	name := fmt.Sprintf("codex-resume-%d", time.Now().UnixNano())

	s, err := c.startTmuxSession(name, dir, home, "codex", "--dangerously-bypass-approvals-and-sandbox", "resume", sessionID)
	if err != nil {
		return nil, err
	}

	// Dismiss any startup prompts until the input prompt appears.
	for range 5 {
		content, waitErr := s.WaitFor(c.PromptPattern(), 15*time.Second)
		if waitErr != nil {
			_ = s.Close()
			return nil, fmt.Errorf("waiting for codex resumed prompt: %w", waitErr)
		}
		if !strings.Contains(content, "press enter to confirm") &&
			!strings.Contains(content, "Use ↑/↓ to move") {
			break
		}
		_ = s.SendKeys("Enter")
		time.Sleep(500 * time.Millisecond)
	}

	return &CodexSession{TmuxSession: s, home: home}, nil
}

func (c *Codex) startTmuxSession(name, dir, home string, args ...string) (*TmuxSession, error) {
	tmuxArgs := append([]string{"CODEX_HOME=" + home, "HOME=" + os.Getenv("HOME"), "TERM=" + os.Getenv("TERM")}, args...)
	return NewTmuxSession(name, dir, []string{"CODEX_HOME", "ENTIRE_TEST_TTY"}, "env", tmuxArgs...)
}

// seedCodexHome writes trust + feature flag config and links auth credentials
// so Codex loads the project's .codex/ layer and can authenticate.
func seedCodexHome(home, projectDir string) error {
	if err := os.MkdirAll(home, 0o750); err != nil {
		return err
	}

	// Write config with trust, feature flag, and pinned model to skip upgrade dialogs.
	model := os.Getenv("E2E_CODEX_MODEL")
	if model == "" {
		model = "gpt-5.4"
	}
	config := fmt.Sprintf("model = %q\n\n[features]\nhooks = true\n\n[projects.%q]\ntrust_level = \"trusted\"\n", model, projectDir)

	// Codex 0.129+ refuses to run unmanaged hooks until each one has a
	// trusted_hash entry in the user's config. Compute the hashes the same
	// way Codex does and pre-trust them — without this, every hook in
	// .codex/hooks.json sits as Untrusted and our hooks never fire under e2e.
	trustState, err := codexHookTrustState(projectDir)
	if err != nil {
		return fmt.Errorf("compute hook trust state: %w", err)
	}
	if trustState != "" {
		config += "\n" + trustState
	}

	if err := os.WriteFile(filepath.Join(home, "config.toml"), []byte(config), 0o600); err != nil {
		return err
	}

	if apiKey := os.Getenv("OPENAI_API_KEY"); apiKey != "" {
		return writeCodexAPIKeyAuth(home, apiKey)
	}

	// Symlink auth.json from the real ~/.codex/ so API credentials are available.
	if realHome, err := os.UserHomeDir(); err == nil {
		src := filepath.Join(realHome, ".codex", "auth.json")
		if _, err := os.Stat(src); err == nil {
			_ = os.Symlink(src, filepath.Join(home, "auth.json"))
		}
	}

	return nil
}

func writeCodexAPIKeyAuth(home, apiKey string) error {
	auth := struct {
		AuthMode     string `json:"auth_mode"`
		OpenAIAPIKey string `json:"OPENAI_API_KEY"`
	}{
		AuthMode:     "apikey",
		OpenAIAPIKey: apiKey,
	}

	data, err := json.MarshalIndent(auth, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal codex auth: %w", err)
	}
	data = append(data, '\n')

	if err := os.WriteFile(filepath.Join(home, "auth.json"), data, 0o600); err != nil {
		return fmt.Errorf("write codex auth: %w", err)
	}

	return nil
}


--- e2e/agents/codex_trust.go
package agents

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

// codexHookFile mirrors the on-disk shape of .codex/hooks.json. Field types
// match Codex's serde definitions (codex-rs/config/src/hook_config.rs) so the
// trust-hash computation below stays faithful to discover_handlers.
type codexHookFile struct {
	Hooks codexHookEvents `json:"hooks"`
}

type codexHookEvents struct {
	PreToolUse        []codexHookGroup `json:"PreToolUse"`
	PermissionRequest []codexHookGroup `json:"PermissionRequest"`
	PostToolUse       []codexHookGroup `json:"PostToolUse"`
	PreCompact        []codexHookGroup `json:"PreCompact"`
	PostCompact       []codexHookGroup `json:"PostCompact"`
	SessionStart      []codexHookGroup `json:"SessionStart"`
	UserPromptSubmit  []codexHookGroup `json:"UserPromptSubmit"`
	Stop              []codexHookGroup `json:"Stop"`
}

type codexHookGroup struct {
	Matcher *string             `json:"matcher"`
	Hooks   []codexHookHandlers `json:"hooks"`
}

type codexHookHandlers struct {
	Type          string  `json:"type"`
	Command       string  `json:"command"`
	Timeout       *uint64 `json:"timeout"`
	Async         bool    `json:"async"`
	StatusMessage *string `json:"statusMessage"`
}

// codexHookEventLabels lists every event name in the order Codex emits in
// the JSON schema, paired with the snake_case label it uses for trust state
// keys (codex-rs/hooks/src/lib.rs:hook_event_key_label).
var codexHookEventLabels = []struct {
	displayName string
	keyLabel    string
}{
	{"PreToolUse", "pre_tool_use"},
	{"PermissionRequest", "permission_request"},
	{"PostToolUse", "post_tool_use"},
	{"PreCompact", "pre_compact"},
	{"PostCompact", "post_compact"},
	{"SessionStart", "session_start"},
	{"UserPromptSubmit", "user_prompt_submit"},
	{"Stop", "stop"},
}

// codexHookTrustState reads .codex/hooks.json from projectDir and returns the
// `[hooks.state.<key>]` TOML block that pre-trusts every command handler
// declared there. The hash matches Codex's command_hook_hash exactly (see
// codex-rs/hooks/src/engine/discovery.rs and config/src/fingerprint.rs):
//
//  1. Build a NormalizedHookIdentity = { event_name, matcher, hooks: [normalized_handler] }
//  2. Serialize to JSON with object keys sorted alphabetically (canonical_json)
//  3. SHA-256 the compact JSON bytes; format as "sha256:<hex>"
//
// Returns empty string when no hooks file exists.
func codexHookTrustState(projectDir string) (string, error) {
	hooksPath := filepath.Join(projectDir, ".codex", "hooks.json")
	data, err := os.ReadFile(hooksPath)
	if err != nil {
		if os.IsNotExist(err) {
			return "", nil
		}
		return "", err
	}

	var file codexHookFile
	if err := json.Unmarshal(data, &file); err != nil {
		return "", fmt.Errorf("parse hooks.json: %w", err)
	}

	var sb strings.Builder
	for _, ev := range codexHookEventLabels {
		groups := codexEventGroups(&file.Hooks, ev.displayName)
		for groupIdx, group := range groups {
			for handlerIdx, handler := range group.Hooks {
				if handler.Type != "command" {
					continue
				}
				timeoutSec := uint64(600)
				if handler.Timeout != nil {
					timeoutSec = *handler.Timeout
				}
				if timeoutSec < 1 {
					timeoutSec = 1
				}
				hash := codexCommandHookHash(ev.keyLabel, group.Matcher, handler.Command, timeoutSec, handler.Async, handler.StatusMessage)
				key := fmt.Sprintf("%s:%s:%d:%d", hooksPath, ev.keyLabel, groupIdx, handlerIdx)
				fmt.Fprintf(&sb, "[hooks.state.%q]\ntrusted_hash = %q\n\n", key, hash)
			}
		}
	}
	return sb.String(), nil
}

func codexEventGroups(events *codexHookEvents, displayName string) []codexHookGroup {
	switch displayName {
	case "PreToolUse":
		return events.PreToolUse
	case "PermissionRequest":
		return events.PermissionRequest
	case "PostToolUse":
		return events.PostToolUse
	case "PreCompact":
		return events.PreCompact
	case "PostCompact":
		return events.PostCompact
	case "SessionStart":
		return events.SessionStart
	case "UserPromptSubmit":
		return events.UserPromptSubmit
	case "Stop":
		return events.Stop
	}
	return nil
}

// codexCommandHookHash mirrors command_hook_hash + version_for_toml. Codex
// builds a TOML value of NormalizedHookIdentity then serde_json::to_value
// converts it to JSON; we skip the TOML round-trip and emit the equivalent
// JSON directly. Crucially:
//   - matcher is omitted when nil (TOML can't represent null Options)
//   - timeout is always present (the normalized handler always sets Some(_))
//   - statusMessage is omitted when nil
//   - object keys are sorted alphabetically by canonicalize before hashing
func codexCommandHookHash(eventLabel string, matcher *string, command string, timeoutSec uint64, async bool, statusMessage *string) string {
	handler := map[string]any{
		"type":    "command",
		"command": command,
		"timeout": json.Number(strconv.FormatUint(timeoutSec, 10)),
		"async":   async,
	}
	if statusMessage != nil {
		handler["statusMessage"] = *statusMessage
	}
	identity := map[string]any{
		"event_name": eventLabel,
		"hooks":      []any{handler},
	}
	if matcher != nil {
		identity["matcher"] = *matcher
	}

	canonical := codexCanonicalJSON(identity)
	sum := sha256.Sum256(canonical)
	return "sha256:" + hex.EncodeToString(sum[:])
}

// codexCanonicalJSON marshals v with object keys sorted alphabetically, no
// whitespace. Go's encoding/json already sorts map[string]any keys, but we
// re-walk explicitly to make the contract obvious and to keep the output
// stable if a future stdlib change reorders.
func codexCanonicalJSON(v any) []byte {
	var buf strings.Builder
	codexWriteCanonical(&buf, v)
	return []byte(buf.String())
}

func codexWriteCanonical(buf *strings.Builder, v any) {
	switch t := v.(type) {
	case map[string]any:
		keys := make([]string, 0, len(t))
		for k := range t {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		buf.WriteByte('{')
		for i, k := range keys {
			if i > 0 {
				buf.WriteByte(',')
			}
			buf.Write(codexJSONAtom(k))
			buf.WriteByte(':')
			codexWriteCanonical(buf, t[k])
		}
		buf.WriteByte('}')
	case []any:
		buf.WriteByte('[')
		for i, item := range t {
			if i > 0 {
				buf.WriteByte(',')
			}
			codexWriteCanonical(buf, item)
		}
		buf.WriteByte(']')
	default:
		buf.Write(codexJSONAtom(t))
	}
}

// codexJSONAtom marshals a scalar matching serde_json's default escaping
// rules: only the JSON-required characters (", \, control chars) are
// escaped — `<`, `>`, `&` pass through unchanged. Go's default json.Marshal
// HTML-escapes those bytes to \u00XX, which would diverge from Codex's
// hash for any command containing shell redirection (>, &&, etc.).
func codexJSONAtom(v any) []byte {
	var b bytes.Buffer
	enc := json.NewEncoder(&b)
	enc.SetEscapeHTML(false)
	// Callers pass strings, bools, and json.Number atoms only; encoding
	// can't fail for those types. Ignore the error rather than complicating
	// every call site for a static guarantee.
	_ = enc.Encode(v) //nolint:errchkjson // scalar atoms only; error is unreachable
	out := b.Bytes()
	if n := len(out); n > 0 && out[n-1] == '\n' {
		out = out[:n-1]
	}
	return out
}


--- e2e/agents/copilot-cli.go
package agents

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"time"
)

func init() {
	if env := os.Getenv("E2E_AGENT"); env != "" && env != "copilot-cli" {
		return
	}
	Register(&CopilotCLI{})
	RegisterGate("copilot-cli", 4)
}

type CopilotCLI struct{}

func (c *CopilotCLI) Name() string               { return "copilot-cli" }
func (c *CopilotCLI) Binary() string             { return "copilot" }
func (c *CopilotCLI) EntireAgent() string        { return "copilot-cli" }
func (c *CopilotCLI) PromptPattern() string      { return `❯` }
func (c *CopilotCLI) TimeoutMultiplier() float64 { return 1.5 }

func (c *CopilotCLI) IsTransientError(out Output, err error) bool {
	if errors.Is(err, context.DeadlineExceeded) {
		return true
	}
	combined := out.Stdout + out.Stderr
	for _, p := range []string{
		"overloaded",
		"rate limit",
		"503",
		"529",
		"ECONNRESET",
		"ETIMEDOUT",
		"Too Many Requests",
		// Copilot sometimes calls its Edit tool without old_str,
		// resulting in zero code changes despite a successful exit.
		"old_str is required",
	} {
		if strings.Contains(combined, p) {
			return true
		}
	}
	return false
}

func (c *CopilotCLI) Bootstrap() error {
	// Copilot CLI uses GitHub authentication (gh auth or GITHUB_TOKEN).
	// No additional bootstrap needed — auth should be pre-configured.
	return nil
}

func (c *CopilotCLI) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
	cfg := &runConfig{Model: "claude-haiku-4.5"}
	for _, o := range opts {
		o(cfg)
	}

	timeout := 60 * time.Second
	if cfg.PromptTimeout > 0 {
		timeout = cfg.PromptTimeout
	}
	promptCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	args := []string{"-p", prompt, "--model", cfg.Model, "--allow-all"}
	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--model", cfg.Model, "--allow-all"}
	cmd := exec.CommandContext(promptCtx, c.Binary(), args...)
	cmd.Dir = dir
	cmd.Stdin = nil
	// GITHUB_COPILOT_PROMPT_MODE_REPO_HOOKS opts in to .github/hooks/*.json loading
	// in -p mode; gated since Copilot 1.0.40 (2026-05-01).
	cmd.Env = append(os.Environ(),
		"ENTIRE_TEST_TTY=0",
		"GITHUB_COPILOT_PROMPT_MODE_REPO_HOOKS=true",
	)
	setupProcessGroup(cmd)
	cmd.WaitDelay = 5 * time.Second

	var stdout, stderr strings.Builder
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	exitCode := 0
	if err != nil {
		exitErr := &exec.ExitError{}
		if errors.As(err, &exitErr) {
			exitCode = exitErr.ExitCode()
		} else {
			exitCode = -1
		}
		if promptCtx.Err() == context.DeadlineExceeded {
			err = fmt.Errorf("%w: %w", err, context.DeadlineExceeded)
		}
	}

	out := Output{
		Command:  c.Binary() + " " + strings.Join(displayArgs, " "),
		Stdout:   stdout.String(),
		Stderr:   stderr.String(),
		ExitCode: exitCode,
	}

	// Copilot sometimes calls its Edit tool without required parameters,
	// producing zero code changes despite exit 0. Surface this as an error so
	// the transient-error retry mechanism can restart the scenario.
	// Only trigger when copilot reports zero changes — it may retry internally.
	if err == nil && strings.Contains(out.Stdout, "old_str is required") &&
		strings.Contains(out.Stderr, "Total code changes:     +0 -0") {
		err = errors.New("copilot Edit tool failed: old_str is required")
	}

	return out, err
}

// CopilotSession wraps TmuxSession to handle Copilot CLI's dual input modes.
// Copilot CLI can be in "Chat" mode (Enter submits) or "Edit" mode (Ctrl+S
// submits). After completing a prompt, copilot may return to either mode
// non-deterministically. This wrapper detects Edit mode after sending Enter
// and falls back to Ctrl+S if needed.
type CopilotSession struct {
	*TmuxSession
}

func (cs *CopilotSession) Send(input string) error {
	if err := cs.clearInputLine(); err != nil {
		return err
	}

	preSend := stableContent(cs.Capture())

	if err := cs.sendOnce(input, preSend); err != nil {
		return err
	}

	// Copilot CLI's autocomplete can non-deterministically trigger during
	// text input (e.g. a "/" in "docs/red.md" opens the slash-command menu).
	// If detected, dismiss with Escape, clear the input, and retry once.
	time.Sleep(300 * time.Millisecond)
	if isAutocompleteMenu(cs.Capture()) {
		if err := cs.dismissAutocompleteAndClear(); err != nil {
			return err
		}
		if err := cs.sendOnce(input, stableContent(cs.Capture())); err != nil {
			return err
		}
	}

	// Copilot can leave behind a stray slash-command invocation between turns.
	// Only retry if that error appeared in output produced by this submission,
	// not merely somewhere in pane scrollback from an earlier turn.
	if content := cs.Capture(); appearedInNewOutput(preSend, content, "Unknown command: /") {
		if err := cs.clearInputLine(); err != nil {
			return err
		}
		if err := cs.sendOnce(input, stableContent(cs.Capture())); err != nil {
			return err
		}
	}

	// Wait for the terminal to reflect the echoed input, then snapshot.
	deadline := time.Now().Add(5 * time.Second)
	for time.Now().Before(deadline) {
		time.Sleep(200 * time.Millisecond)
		current := stableContent(cs.Capture())
		if current != preSend {
			cs.stableAtSend = current
			return nil
		}
	}
	cs.stableAtSend = stableContent(cs.Capture())
	return nil
}

// clearInputLine removes any partially typed prompt text without sending other
// UI navigation keys. In Copilot CLI, Escape can trigger undo/snapshot actions,
// so routine pre-send cleanup must avoid it.
func (cs *CopilotSession) clearInputLine() error {
	if err := cs.SendKeys("C-u"); err != nil {
		return err
	}
	time.Sleep(200 * time.Millisecond)
	return nil
}

// dismissAutocompleteAndClear closes the slash-command autocomplete dropdown
// and then clears the input line before retrying the prompt.
func (cs *CopilotSession) dismissAutocompleteAndClear() error {
	if err := cs.SendKeys("Escape"); err != nil {
		return err
	}
	time.Sleep(200 * time.Millisecond)
	return cs.clearInputLine()
}

// appearedInNewOutput reports whether pattern is present in content that was
// added after the pre-send snapshot. This avoids retriggering on old pane
// scrollback from previous turns.
func appearedInNewOutput(before string, after string, pattern string) bool {
	if after == before {
		return false
	}
	if strings.HasPrefix(after, before) {
		return strings.Contains(after[len(before):], pattern)
	}

	// If tmux capture lost a clean prefix relationship due to scrollback churn,
	// fall back to checking only the most recent lines.
	lines := strings.Split(after, "\n")
	start := max(0, len(lines)-12)
	return strings.Contains(strings.Join(lines[start:], "\n"), pattern)
}

// sendOnce types the input text, sends Enter, and handles Edit mode fallback.
func (cs *CopilotSession) sendOnce(input string, preSend string) error {
	// Use -l (literal) flag to prevent tmux from interpreting characters
	// in the prompt text as special key names.
	args := []string{"send-keys", "-l", "-t", cs.name, input}
	cmd := exec.Command("tmux", args...)
	if out, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("tmux send-keys -l: %w\n%s", err, out)
	}
	time.Sleep(200 * time.Millisecond)
	if err := cs.SendKeys("Enter"); err != nil {
		return err
	}

	// Briefly poll to see if copilot is still in Edit mode (Enter didn't submit).
	// In Edit mode the status bar shows "ctrl+s run command". If detected,
	// send Ctrl+S to actually submit the prompt. Break early if the content
	// changes from the pre-send snapshot, indicating submission has started.
	editDeadline := time.Now().Add(500 * time.Millisecond)
	for time.Now().Before(editDeadline) {
		content := cs.Capture()
		if isEditMode(content) {
			if err := cs.SendKeys("C-s"); err != nil {
				return err
			}
			break
		}
		if stableContent(content) != preSend {
			break
		}
		time.Sleep(50 * time.Millisecond)
	}
	return nil
}

// isEditMode checks if copilot-cli is in Edit mode by looking for the
// "ctrl+s run command" indicator in the last few lines (status bar area).
// Restricting the search avoids false positives if the phrase appears in
// agent output.
func isEditMode(content string) bool {
	lines := strings.Split(content, "\n")
	const statusPhrase = "ctrl+s run command"
	for i := len(lines) - 1; i >= 0 && i >= len(lines)-3; i-- {
		if strings.Contains(lines[i], statusPhrase) {
			return true
		}
	}
	return false
}

// isAutocompleteMenu detects copilot's slash-command autocomplete dropdown.
// When triggered, copilot shows a list of commands starting with "▋  /"
// below the input line, preventing prompt submission.
func isAutocompleteMenu(content string) bool {
	lines := strings.Split(content, "\n")
	matches := 0
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "▋") && strings.Contains(trimmed, "/") {
			matches++
			if matches >= 2 {
				return true
			}
		}
	}
	return false
}

func (c *CopilotCLI) StartSession(ctx context.Context, dir string) (Session, error) {
	bin, err := exec.LookPath(c.Binary())
	if err != nil {
		return nil, fmt.Errorf("agent binary not found: %w", err)
	}

	// Forward auth-related env vars into the tmux session. tmux starts a new
	// shell that doesn't inherit Go's os.Environ(), so without this the
	// session can lose both token-based auth and local gh/copilot login state.
	var envArgs []string
	for _, key := range []string{"COPILOT_GITHUB_TOKEN", "HOME", "TERM", "XDG_CONFIG_HOME", "GH_CONFIG_DIR"} {
		if v := os.Getenv(key); v != "" {
			envArgs = append(envArgs, key+"="+v)
		}
	}
	args := append([]string{"env"}, envArgs...)
	args = append(args, bin, "--model", "claude-haiku-4.5", "--allow-all")

	name := fmt.Sprintf("copilot-test-%d", time.Now().UnixNano())
	// Strip CI env vars that may affect interactive mode.
	unset := []string{"CI", "GITHUB_ACTIONS", "ENTIRE_TEST_TTY"}
	s, err := NewTmuxSession(name, dir, unset, args[0], args[1:]...)
	if err != nil {
		return nil, err
	}

	// Dismiss startup dialogs (folder trust, etc.) then wait for the "❯" prompt.
	// Copilot CLI shows a "Confirm folder trust" dialog in interactive mode for
	// new directories. "Yes" is pre-selected, so Enter dismisses it.
	foundPrompt := false
	for range 5 {
		content, err := s.WaitFor(`(❯|Enter to select)`, 30*time.Second)
		if err != nil {
			_ = s.Close()
			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
		}
		if strings.Contains(content, "❯") && !strings.Contains(content, "Enter to select") {
			foundPrompt = true
			break
		}
		if err := s.SendKeys("Enter"); err != nil {
			_ = s.Close()
			return nil, fmt.Errorf("dismissing startup dialog: %w", err)
		}
		time.Sleep(500 * time.Millisecond)
	}
	if !foundPrompt {
		_ = s.Close()
		return nil, errors.New("copilot CLI did not reach interactive prompt after dismissing startup dialogs")
	}
	s.stableAtSend = ""

	return &CopilotSession{TmuxSession: s}, nil
}


--- e2e/agents/cursor_cli.go
package agents

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

func init() {
	if env := os.Getenv("E2E_AGENT"); env != "" && env != "cursor-cli" {
		return
	}
	Register(&CursorCLI{})
}

// CursorCLI implements the E2E Agent interface for the Cursor Agent CLI binary.
// The CLI binary is called "agent" and uses Cursor's hooks system via
// .cursor/hooks.json. It maps to the same Entire agent as Cursor IDE ("cursor").
//
// All E2E interactions use interactive (tmux) mode so that the full hook
// lifecycle fires (sessionStart, beforeSubmitPrompt, stop, sessionEnd).
// Headless (-p) mode skips beforeSubmitPrompt and stop hooks.
type CursorCLI struct{}

func (a *CursorCLI) Name() string               { return "cursor-cli" }
func (a *CursorCLI) Binary() string             { return "agent" }
func (a *CursorCLI) EntireAgent() string        { return "cursor" }
func (a *CursorCLI) TimeoutMultiplier() float64 { return 1.5 }

// PromptPattern returns a regex matching Cursor's ready-state prompt markers.
// Cursor has used multiple startup/completion markers across releases.
func (a *CursorCLI) PromptPattern() string {
	return `(/ commands|Plan, search, build anything|Add a follow-up)`
}

func (a *CursorCLI) IsTransientError(out Output, err error) bool {
	if err == nil {
		return false
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return true
	}
	combined := out.Stdout + out.Stderr
	for _, p := range []string{
		"overloaded",
		"rate limit",
		"429",
		"503",
		"529",
		"ECONNRESET",
		"ETIMEDOUT",
		"server error",
		"Internal Server Error",
	} {
		if strings.Contains(combined, p) {
			return true
		}
	}
	return false
}

func (a *CursorCLI) Bootstrap() error {
	// The Cursor CLI authenticates via CURSOR_API_KEY env var or OAuth.
	// On CI, ensure CURSOR_API_KEY is set. Locally, OAuth/keychain works.
	if os.Getenv("CI") != "" && os.Getenv("CURSOR_API_KEY") == "" {
		return errors.New("CURSOR_API_KEY must be set on CI for cursor-cli E2E tests")
	}
	return nil
}

// cursorConfigDir creates an isolated per-session config directory for the
// Cursor CLI. Each session gets its own XDG_CONFIG_HOME so that parallel tests
// don't race on the shared ~/.config/cursor/cli-config.json file.
// The directory is pre-seeded with an empty cli-config.json to avoid the
// atomic temp-file rename that triggers the ENOENT race.
func cursorConfigDir() (string, error) {
	tmp, err := os.MkdirTemp("", "cursor-e2e-config-*")
	if err != nil {
		return "", fmt.Errorf("create temp config dir: %w", err)
	}
	cursorDir := filepath.Join(tmp, "cursor")
	if err := os.MkdirAll(cursorDir, 0o755); err != nil {
		return "", fmt.Errorf("mkdir cursor config: %w", err)
	}
	if err := os.WriteFile(filepath.Join(cursorDir, "cli-config.json"), []byte("{}"), 0o644); err != nil {
		return "", fmt.Errorf("seed cli-config.json: %w", err)
	}
	return tmp, nil
}

func (a *CursorCLI) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
	cfg := &runConfig{}
	for _, o := range opts {
		o(cfg)
	}

	timeout := 90 * time.Second
	if cfg.PromptTimeout > 0 {
		timeout = cfg.PromptTimeout
	}

	displayCmd := a.Binary() + " --force --workspace " + dir + " (interactive prompt: " + prompt + ")"

	// Start an interactive tmux session so all hooks fire
	// (beforeSubmitPrompt and stop don't fire in headless -p mode).
	s, err := a.startInteractiveSession(dir)
	if err != nil {
		return Output{Command: displayCmd, ExitCode: -1},
			fmt.Errorf("start interactive session: %w", err)
	}
	defer s.Close()

	// Wait for trust dialog and accept it.
	if err := a.acceptTrustDialogIfNeeded(s); err != nil {
		return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1}, err
	}

	// Wait for the TUI to be ready.
	if _, err := s.WaitFor(a.PromptPattern(), 45*time.Second); err != nil {
		return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1},
			fmt.Errorf("waiting for startup prompt: %w", err)
	}

	// Send the prompt.
	if err := s.Send(prompt); err != nil {
		return Output{Command: displayCmd, Stdout: s.Capture(), ExitCode: -1},
			fmt.Errorf("sending prompt: %w", err)
	}

	// One absolute deadline covers both the "Add a follow-up" wait and the
	// subsequent busy-hint wait, so the whole RunPrompt call honors the
	// caller-provided timeout (rather than ~2× it across two stages).
	deadline := time.Now().Add(timeout)

	// Wait for the "Add a follow-up" input placeholder. This alone isn't
	// sufficient — Cursor renders the placeholder while the agent is still
	// editing, alongside a busy-state hint "ctrl+c to stop" on the same line
	// (and the "Editing N tokens" spinner above). If we return now, the
	// caller's defer s.Close() kills tmux mid-turn, the cursor process exits
	// before its `stop` hook fires, SaveStep never runs, and the resulting
	// checkpoint has empty FilesTouched.
	content, waitErr := s.WaitFor(`Add a follow-up`, time.Until(deadline))
	if waitErr != nil {
		// Check for deadline exceeded to allow transient error detection.
		if ctx.Err() == context.DeadlineExceeded {
			waitErr = fmt.Errorf("%w: %w", waitErr, context.DeadlineExceeded)
		}
		return Output{Command: displayCmd, Stdout: content, ExitCode: -1}, waitErr
	}

	// Then wait for the busy hint to disappear, confirming the agent has
	// finished its turn so the `stop` hook can fire before tmux is torn down.
	for {
		if !strings.Contains(content, "ctrl+c to stop") {
			return Output{Command: displayCmd, Stdout: content, ExitCode: 0}, nil
		}
		remaining := time.Until(deadline)
		if remaining <= 0 {
			err := fmt.Errorf("cursor agent did not finish turn (ctrl+c to stop still visible) within %s", timeout)
			if ctx.Err() == context.DeadlineExceeded {
				err = fmt.Errorf("%w: %w", err, context.DeadlineExceeded)
			}
			return Output{Command: displayCmd, Stdout: content, ExitCode: -1}, err
		}
		sleep := 200 * time.Millisecond
		if remaining < sleep {
			sleep = remaining
		}
		select {
		case <-ctx.Done():
			return Output{Command: displayCmd, Stdout: content, ExitCode: -1},
				fmt.Errorf("waiting for cursor agent to finish turn: %w", ctx.Err())
		case <-time.After(sleep):
		}
		content = s.Capture()
	}
}

func (a *CursorCLI) StartSession(ctx context.Context, dir string) (Session, error) {
	s, err := a.startInteractiveSession(dir)
	if err != nil {
		return nil, err
	}

	if err := a.acceptTrustDialogIfNeeded(s); err != nil {
		_ = s.Close()
		return nil, err
	}

	// Wait for the TUI to be ready (input prompt).
	if _, err := s.WaitFor(a.PromptPattern(), 45*time.Second); err != nil {
		_ = s.Close()
		return nil, fmt.Errorf("waiting for startup prompt: %w", err)
	}
	s.stableAtSend = ""

	return s, nil
}

// startInteractiveSession creates a new tmux session running the Cursor CLI
// in interactive mode (no -p flag) so all hooks fire.
func (a *CursorCLI) startInteractiveSession(dir string) (*TmuxSession, error) {
	// Resolve to absolute path so tmux can find the binary even if its
	// shell doesn't inherit the test process's PATH (common on CI).
	bin, err := exec.LookPath(a.Binary())
	if err != nil {
		return nil, fmt.Errorf("agent binary not found: %w", err)
	}

	// Create an isolated config directory for this session so parallel tests
	// don't race on the shared ~/.config/cursor/cli-config.json file.
	configDir, err := cursorConfigDir()
	if err != nil {
		return nil, fmt.Errorf("create cursor config dir: %w", err)
	}

	// Build env-wrapped command so the tmux session inherits critical env vars.
	// tmux starts a new shell that doesn't inherit Go's os.Environ().
	var envArgs []string
	for _, key := range []string{"CURSOR_API_KEY", "PATH", "HOME", "TERM"} {
		if v := os.Getenv(key); v != "" {
			envArgs = append(envArgs, key+"="+v)
		}
	}
	// Point XDG_CONFIG_HOME to our isolated dir so cursor writes its config
	// there instead of ~/.config/cursor/. We keep the real HOME so that
	// auth credentials (keychain, OAuth tokens) remain accessible.
	envArgs = append(envArgs, "XDG_CONFIG_HOME="+configDir)

	args := append([]string{"env"}, envArgs...)
	args = append(args, bin, "--force", "--workspace", dir)

	name := fmt.Sprintf("cursor-cli-test-%d", time.Now().UnixNano())
	unset := []string{"CI"}
	s, err := NewTmuxSession(name, dir, unset, args[0], args[1:]...)
	if err != nil {
		_ = os.RemoveAll(configDir)
		return nil, err
	}
	s.OnClose(func() { _ = os.RemoveAll(configDir) })
	return s, nil
}

// acceptTrustDialogIfNeeded checks whether the workspace trust dialog appears
// and presses "a" to accept it. The dialog only shows on the first launch in
// a workspace — subsequent sessions in the same directory skip it.
func (a *CursorCLI) acceptTrustDialogIfNeeded(s *TmuxSession) error {
	// Race: either the trust dialog or the input prompt will appear first.
	// Use a short timeout to check for the trust dialog without blocking
	// too long if the workspace is already trusted.
	content, err := s.WaitFor(`Trust this workspace|`+a.PromptPattern(), 45*time.Second)
	if err != nil {
		return fmt.Errorf("waiting for trust dialog or prompt: %w", err)
	}
	if strings.Contains(content, "Trust this workspace") {
		if err := s.SendKeys("a"); err != nil {
			return fmt.Errorf("accepting trust dialog: %w", err)
		}
	}
	return nil
}


